<template><div class="activity-page"><WorkspaceHero eyebrow="CAMPUS OPPORTUNITIES" title="校园活动与实践机会" description="从已发布的校园通知中寻找适合自己的活动，先核对来源、报名时间与费用，再安排成长行动。"/>
  <form class="card activity-filters" @submit.prevent="load"><el-select v-model="filters.academicYear" aria-label="活动适用学年"><el-option v-for="y in years" :key="y" :label="y" :value="y"/></el-select><el-select v-model="filters.focusKey" aria-label="关注方向"><el-option label="全部方向" value=""/><el-option v-for="(label,key) in focus" :key="key" :label="label" :value="key"/></el-select><el-select v-model="filters.maxMinutes" aria-label="可投入时长"><el-option label="不限活动时长" :value="0"/><el-option v-for="minutes in [30,60,120,180]" :key="minutes" :label="`不超过 ${minutes} 分钟`" :value="minutes"/></el-select><el-input v-model="filters.keyword" aria-label="活动关键词" maxlength="100" placeholder="活动名称或关键词" clearable/><el-button native-type="submit" type="primary" :loading="loading">查看匹配活动</el-button></form>
  <p class="activity-note">{{notice||'只展示当前仍可报名且适用于本人的已发布活动；活动时长与方向由自己选择。'}}</p><p v-if="dirty" class="activity-note">筛选已调整，请重新查看匹配活动。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-alert v-if="requestedActivity&&!loading&&!items.some(item=>item.id===requestedActivity)" title="所选活动不在当前可报名清单中，可能已截止、修订、撤回或不符合筛选条件，请联系主办方确认。" type="warning" :closable="false"/>
  <section v-loading="loading" class="activity-grid"><el-empty v-if="!loading&&!items.length&&!error&&!dirty" description="暂无符合条件的已发布活动。可调整筛选，或联系教师发布当前校园通知。"/>
    <article v-for="item in items" :key="item.id" class="card activity-card"><div class="activity-meta"><span>{{focus[item.data.focusKey]}}</span><small>来源版本 v{{item.revision}}</small></div><h2>{{item.data.title}}</h2><p>{{item.data.summary||item.data.description}}</p><dl><div><dt>报名截止</dt><dd>{{time(item.data.registrationEndAt)}}</dd></div><div><dt>活动时间</dt><dd>{{time(item.data.startsAt)}} 至 {{time(item.data.endsAt)}}</dd></div><div><dt>地点 · 时长</dt><dd>{{item.data.location}} · 约 {{item.data.durationMinutes}} 分钟</dd></div><div><dt>发布单位</dt><dd>{{item.data.issuer}}</dd></div><div><dt>费用说明</dt><dd>{{item.data.costDescription}}</dd></div></dl><div class="matching-reasons"><strong>为什么显示给我</strong><span v-for="reason in item.reasons" :key="reason">{{reason}}</span></div><details><summary>阅读完整活动说明</summary><p class="activity-description">{{item.data.description}}</p></details><footer><a v-if="safeHttps(item.data.sourceUrl)" :href="item.data.sourceUrl" target="_blank" rel="noopener noreferrer">查看来源通知 ↗</a><a v-if="safeHttps(item.data.registrationUrl)" :href="item.data.registrationUrl" target="_blank" rel="noopener noreferrer">前往主办方报名 ↗</a></footer><el-button type="primary" plain :loading="joining===item.id" :disabled="!!joining||joined.includes(item.seriesId)" @click="join(item)">{{joined.includes(item.seriesId)?'已加入本次计划':'加入成长计划'}}</el-button></article>
  </section><section class="card activity-plan-target"><div><strong>安排到哪个成长计划</strong><p>加入只创建一条待行动任务，不代替主办方报名，也不会自动增加综测分数。活动修订后请再次核对来源通知。</p></div><el-select v-model="semester" aria-label="目标成长计划学期"><el-option label="第一学期" value="first"/><el-option label="第二学期" value="second"/><el-option label="年度" value="annual"/></el-select><el-button @click="router.push({path:'/growth-plan',query:{academicYear:filters.academicYear,semester}})">查看或保存成长计划</el-button></section>
</div></template>
<script setup>
import {ref,reactive,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import WorkspaceHero from '@/components/WorkspaceHero.vue';import {getCampusActivities,addActivityToPlan} from '@/api/guidance';import {getGrowthPlan} from '@/api/growth-plans';
const route=useRoute();const router=useRouter();const focus={morality:'德育实践',academy:'学习与创新',sports:'体育健康',arts:'美育实践',labor:'劳动与志愿服务'};const start=new Date().getFullYear()-(new Date().getMonth()<8?1:0);const years=Array.from({length:5},(_,i)=>`${start+1-i}-${start+2-i}`);
const filters=reactive({academicYear:/^\d{4}-\d{4}$/.test(String(route.query.academicYear||''))?route.query.academicYear:`${start}-${start+1}`,focusKey:Object.hasOwn(focus,route.query.focusKey)?route.query.focusKey:'',maxMinutes:[30,60,120,180].includes(Number(route.query.maxMinutes))?Number(route.query.maxMinutes):0,keyword:''});const semester=ref(['first','second','annual'].includes(route.query.semester)?route.query.semester:new Date().getMonth()>=8||new Date().getMonth()===0?'first':'second');const requestedActivity=Number(route.query.activityId)||null;
const items=ref([]);const loading=ref(false);const error=ref('');const notice=ref('');const dirty=ref(false);const joining=ref(null);const joined=ref([]);let version=0;
const time=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
function safeHttps(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}}
watch(filters,()=>{version++;items.value=[];error.value='';notice.value='';loading.value=false;dirty.value=true;joined.value=[];},{flush:'sync'});watch(semester,()=>{joined.value=[];});
async function load(){const current=++version;loading.value=true;error.value='';dirty.value=false;items.value=[];try{const result=await getCampusActivities({...filters});if(current===version){items.value=result.items;notice.value=result.notice+(result.limited?' 单次最多读取 500 条发布记录，请联系维护人员归档过期内容。':'');}}catch(err){if(current===version)error.value=err.message||'活动加载失败，请刷新重试';}finally{if(current===version)loading.value=false;}}
async function join(item){if(joining.value)return;const current=version;const period={academicYear:filters.academicYear,semester:semester.value};joining.value=item.id;try{const result=await getGrowthPlan(period);if(current!==version||semester.value!==period.semester)return;if(!result.plan){ElMessage.warning('请先通过页面下方入口保存本学期成长计划');return;}await addActivityToPlan(item.id,{...period,revision:result.plan.revision});if(current===version&&semester.value===period.semester){joined.value.push(item.seriesId);ElMessage.success('已加入成长计划，请自行核对主办方报名要求');}}catch(err){if(current===version)ElMessage.error(err.message||'未能加入，请刷新活动与计划后重试');}finally{joining.value=null;}}
onMounted(load);onBeforeUnmount(()=>{version++;});
</script>
<style scoped>
.activity-page{--ink:#203c5c;--muted:#687d95;}.activity-filters{display:flex;gap:12px;flex-wrap:wrap;padding:20px;margin:20px 0 14px;}.activity-filters .el-select{width:170px;}.activity-filters .el-input{flex:1;min-width:180px;}.activity-note{font-size:12px;color:var(--muted);line-height:1.9;}.activity-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:20px;}.activity-grid>.el-empty{grid-column:1/-1;}.activity-card{padding:25px;min-width:0;border-top:3px solid #188a88;}.activity-meta{display:flex;justify-content:space-between;gap:12px;color:#117d79;font-size:12px;}.activity-meta small{color:var(--muted);font-size:11px;}.activity-card h2{font-size:21px;line-height:1.6;color:var(--ink);margin:16px 0 10px;overflow-wrap:anywhere;}.activity-card>p{font-size:13px;line-height:1.9;color:var(--muted);}.activity-card dl{margin:22px 0;font-size:12px;line-height:1.8;}.activity-card dl>div{display:grid;grid-template-columns:82px minmax(0,1fr);gap:12px;margin-bottom:10px;}.activity-card dt{color:var(--muted);}.activity-card dd{margin:0;color:var(--ink);overflow-wrap:anywhere;}.matching-reasons{padding:15px;background:#eef8f5;color:#14766b;font-size:12px;line-height:1.9;}.matching-reasons strong,.matching-reasons span{display:block;}.activity-card details{margin:18px 0;font-size:12px;line-height:1.8;}.activity-card summary{cursor:pointer;color:#287bc8;}.activity-description{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);}.activity-card footer{display:flex;flex-wrap:wrap;gap:15px;margin:18px 0;}.activity-card a{font-size:12px;color:#287bc8;}.activity-plan-target{display:flex;align-items:center;flex-wrap:wrap;gap:16px;padding:24px;margin-top:24px;}.activity-plan-target>div:first-child{flex:1;min-width:240px;color:var(--ink);font-size:14px;}.activity-plan-target p{font-size:12px;color:var(--muted);line-height:1.8;}.activity-plan-target .el-select{width:150px;}.activity-card a:focus-visible,.activity-card summary:focus-visible{outline:2px solid #287bc8;outline-offset:3px;}@media(max-width:850px){.activity-grid{grid-template-columns:minmax(0,1fr);}}@media(max-width:550px){.activity-filters{padding:16px;}.activity-filters .el-select,.activity-filters .el-input{width:100%;flex:auto;min-width:0;}.activity-card{padding:20px 16px;}.activity-plan-target{padding:20px 16px;}.activity-plan-target .el-select{width:100%;}}
</style>
